195	  if (!section || !head || !actions) return;
196	
197	  aboutSceneDomState.isContactHeadVisible = false;
198	  aboutSceneDomState.contactHeadTimers = clearTimers(
199	    aboutSceneDomState.contactHeadTimers,
200	  );
201	  section.dataset.active = "false";
202	  head.dataset.active = "false";
203	  actions.dataset.active = "false";
204	
205	  const textItems = Array.from(head.querySelectorAll<HTMLElement>(".mask-target"));
206	  textItems.forEach((item) => TextReveal.setVisibleOff(item));
207	}
