import type { PageThreeConfig } from "../../../types/core.types.js";
import type { AboutInitialState } from "../../../types/about.types.js";
import * as THREE from "three";
import { getDefaultThreeConfig } from "../../../config/base.config.js";
import {
  aboutLights,
  aboutBackground,
  astronaut,
  earth,
  gravityBalls,
  jetEngine,
  rocket,
  terrian,
} from "../../../core/setup.js";
import {
  ABOUT_DEFAULT_SCENE_STATE,
  cloneAboutSceneState,
} from "../theatre/AboutSceneState.js";
import type {
  AboutPageConfig,
  AboutSceneSectionKey,
  AboutTheatreSheetId,
} from "../../../types/about.types.js";
import type {
  PageSceneRuntimePolicy,
  SceneBackgroundPolicy,
  SceneProgressOptionsMap,
  SceneSelectorMap,
} from "../../../types/runtime.types.js";
import { TextReveal } from "../../../animation/TextReveal.js";
import { runIntroDomTimeline } from "../../../runtime/IntroLoadingRuntime.js";
import {
  BACKGROUND_APP_DOM as APP_MANAGER_DOM,
  CONTACT_HEAD_TRANSITION,
} from "../../../config/transition.config.js";
import {
  resolveAboutAuthorMode,
  resolveAboutPreviewMode,
} from "../theatre/AboutTheatreConfig.js";

const aboutIntroOverlay = { tl: runIntroDomTimeline };
let didRunAboutDomInit = false;
const ABOUT_IS_AUTHOR_MODE = resolveAboutAuthorMode();
const ABOUT_IS_THEATRE_PREVIEW_MODE = resolveAboutPreviewMode();
const ABOUT_HERO_SLOGAN_SELECTOR =
  '.no-sub-about-hero-slogan[data-scene="heroSlogan"]';
const ABOUT_HERO_SLOGAN_ALPHA_MIN = 0.24;
const ABOUT_HERO_SLOGAN_ALPHA_MAX = 0.88;
const ABOUT_HERO_SLOGAN_ALPHA_SPAN =
  ABOUT_HERO_SLOGAN_ALPHA_MAX - ABOUT_HERO_SLOGAN_ALPHA_MIN;
const ABOUT_HERO_SLOGAN_ALPHA_PROPERTY = "--hero-slogan-surface-alpha";
const ABOUT_JOURNEY_SURFACE_SELECTOR = ".no-sub-about-journey-surface";
const ABOUT_JOURNEY_SURFACE_ALPHA_MIN = 0.24;
const ABOUT_JOURNEY_SURFACE_ALPHA_MAX = 0.72;
const ABOUT_JOURNEY_SURFACE_ALPHA_PROPERTY = "--about-journey-surface-alpha";
const ABOUT_JOURNEY_SURFACE_SEGMENT_SPAN =
  (ABOUT_JOURNEY_SURFACE_ALPHA_MAX - ABOUT_JOURNEY_SURFACE_ALPHA_MIN) / 3;
const ABOUT_CONTACT_SECTION_SELECTOR = '.no-main-contact[data-scene="contact"]';
const ABOUT_CONTACT_HEAD_SELECTOR = ".no-main-contact__head";
const ABOUT_CONTACT_ACTIONS_SELECTOR = ".no-main-contact__actions";
let aboutHeroSloganElement: HTMLElement | null = null;
let aboutJourneySurfaceElement: HTMLElement | null = null;
const aboutSceneDomState = {
  isContactHeadVisible: false,
  contactHeadTimers: [] as number[],
};

const aboutBaselineSceneState = cloneAboutSceneState(ABOUT_DEFAULT_SCENE_STATE);
const defaultThree = getDefaultThreeConfig();

function getAboutHeroSloganElement(): HTMLElement | null {
  if (aboutHeroSloganElement?.isConnected) {
    return aboutHeroSloganElement;
  }
  aboutHeroSloganElement = document.querySelector<HTMLElement>(
    ABOUT_HERO_SLOGAN_SELECTOR,
  );
  return aboutHeroSloganElement;
}

function getAboutJourneySurfaceElement(): HTMLElement | null {
  if (aboutJourneySurfaceElement?.isConnected) {
    return aboutJourneySurfaceElement;
  }
  aboutJourneySurfaceElement = document.querySelector<HTMLElement>(
    ABOUT_JOURNEY_SURFACE_SELECTOR,
  );
  return aboutJourneySurfaceElement;
}

function setAboutHeroSloganSurfaceAlpha(progress: number): void {
  const element = getAboutHeroSloganElement();
  if (!element) return;
  const clampedProgress = Math.max(0, Math.min(1, progress));
  const alpha =
    ABOUT_HERO_SLOGAN_ALPHA_MIN +
    ABOUT_HERO_SLOGAN_ALPHA_SPAN * clampedProgress;
  element.style.setProperty(ABOUT_HERO_SLOGAN_ALPHA_PROPERTY, alpha.toFixed(4));
}

function resetAboutHeroSloganSurfaceAlpha(): void {
  const element = getAboutHeroSloganElement();
  if (!element) return;
  element.style.setProperty(
    ABOUT_HERO_SLOGAN_ALPHA_PROPERTY,
    String(ABOUT_HERO_SLOGAN_ALPHA_MIN),
  );
}

function setAboutJourneySurfaceAlpha(alpha: number): void {
  const element = getAboutJourneySurfaceElement();
  if (!element) return;
  element.style.setProperty(ABOUT_JOURNEY_SURFACE_ALPHA_PROPERTY, alpha.toFixed(4));
}

function syncAboutMissionVisionSurfaceAlpha(progress: number): void {
  const clampedProgress = Math.max(0, Math.min(1, progress));
  const alpha =
    ABOUT_JOURNEY_SURFACE_ALPHA_MIN +
    ABOUT_JOURNEY_SURFACE_SEGMENT_SPAN * clampedProgress;
  setAboutJourneySurfaceAlpha(alpha);
}

function syncAboutServicesSurfaceAlpha(progress: number): void {
  const clampedProgress = Math.max(0, Math.min(1, progress));
  const alpha =
    ABOUT_JOURNEY_SURFACE_ALPHA_MIN +
    ABOUT_JOURNEY_SURFACE_SEGMENT_SPAN +
    ABOUT_JOURNEY_SURFACE_SEGMENT_SPAN * clampedProgress;
  setAboutJourneySurfaceAlpha(alpha);
}

function syncAboutAwardsSurfaceAlpha(progress: number): void {
  const clampedProgress = Math.max(0, Math.min(1, progress));
  const alpha =
    ABOUT_JOURNEY_SURFACE_ALPHA_MIN +
    ABOUT_JOURNEY_SURFACE_SEGMENT_SPAN * 2 +
    ABOUT_JOURNEY_SURFACE_SEGMENT_SPAN * clampedProgress;
  setAboutJourneySurfaceAlpha(alpha);
}

function resetAboutJourneySurfaceAlpha(): void {
  setAboutJourneySurfaceAlpha(ABOUT_JOURNEY_SURFACE_ALPHA_MIN);
}

function clearTimers(timerIds: number[]): number[] {
  timerIds.forEach((timerId) => {
    window.clearTimeout(timerId);
  });
  return [];
}


function syncAboutContactHead(progress: number): void {
  const section = document.querySelector<HTMLElement>(ABOUT_CONTACT_SECTION_SELECTOR);
  const head = document.querySelector<HTMLElement>(ABOUT_CONTACT_HEAD_SELECTOR);
  const actions = document.querySelector<HTMLElement>(ABOUT_CONTACT_ACTIONS_SELECTOR);
  if (!section || !head || !actions) return;

  const textItems = Array.from(head.querySelectorAll<HTMLElement>(".mask-target"));
  const shouldShow = progress >= CONTACT_HEAD_TRANSITION.revealStart;

  if (aboutSceneDomState.isContactHeadVisible === shouldShow) return;
  aboutSceneDomState.isContactHeadVisible = shouldShow;
  aboutSceneDomState.contactHeadTimers = clearTimers(
    aboutSceneDomState.contactHeadTimers,
  );

  if (shouldShow) {
    section.dataset.active = "true";
    head.dataset.active = "true";
    actions.dataset.active = "true";
    TextReveal.setVisibleOff(textItems);
    textItems.forEach((item, index) => {
      const timerId = window.setTimeout(() => {
        TextReveal.setVisibleOn(item);
      }, index * CONTACT_HEAD_TRANSITION.revealStagger * 1000);
      aboutSceneDomState.contactHeadTimers.push(timerId);
    });
    return;
  }

  textItems.forEach((item) => {
    TextReveal.setVisibleOff(item);
  });
  section.dataset.active = "false";
  head.dataset.active = "false";
  actions.dataset.active = "false";
}

function disposeAboutContactHead(): void {
  const section = document.querySelector<HTMLElement>(ABOUT_CONTACT_SECTION_SELECTOR);
  const head = document.querySelector<HTMLElement>(ABOUT_CONTACT_HEAD_SELECTOR);
  const actions = document.querySelector<HTMLElement>(ABOUT_CONTACT_ACTIONS_SELECTOR);
  if (!section || !head || !actions) return;

  aboutSceneDomState.isContactHeadVisible = false;
  aboutSceneDomState.contactHeadTimers = clearTimers(
    aboutSceneDomState.contactHeadTimers,
  );
  section.dataset.active = "false";
  head.dataset.active = "false";
  actions.dataset.active = "false";

  const textItems = Array.from(head.querySelectorAll<HTMLElement>(".mask-target"));
  textItems.forEach((item) => TextReveal.setVisibleOff(item));
}

function createAboutInitialState(
